// CreateTableWithDBType creates the FA_Journal_Line table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *FAJournalLine) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FAJournalLineTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetFAJournalLinePostgresTableSchema()
	} else {
		schema = GetFAJournalLineTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create FA_Journal_Line table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *FAJournalLine) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FAJournalLineTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (journal_template_name, journal_batch_name, line_no)`,
		fmt.Sprintf("%s$FA_Journal_Line$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (journal_template_name, journal_batch_name, fa_posting_date)`,
		fmt.Sprintf("%s$FA_Journal_Line$fa_posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_posting_date: %w", err)
	}
	var keys []sift.Key
	for _, spec := range fAJournalLineSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, FAJournalLineTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, FAJournalLineTableName, keys)
}

// fAJournalLineSIFTSpecs are the table's keys with sum_index_fields
func fAJournalLineSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *FAJournalLine) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, FAJournalLineTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range fAJournalLineSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, FAJournalLineTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: FAJournalLineTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, FAJournalLineTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

